export const getEndCaseAssignmentUrl = (
  caseId: string,
  assignmentId: string,
) => {
  return `/api/cases/${caseId}/assignments/${assignmentId}/end`;
};

export const endCaseAssignment = async (
  caseId: string,
  assignmentId: string,
  options?: RequestInit,
): Promise<void> => {
  return orbitApiFetch<void>(getEndCaseAssignmentUrl(caseId, assignmentId), {
    ...options,
    method: "POST",
  });
};

export const getEndCaseAssignmentMutationKey = () =>
  ["endCaseAssignment"] as const;

export const getEndCaseAssignmentMutationOptions = <
  TError =
    | UnauthorizedError
    | ForbiddenError
    | OrganizationRequiredError
    | RateLimitedError,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof endCaseAssignment>>,
    TError,
    EndCaseAssignmentMutationVariables,
    TContext
  >;
}): UseMutationOptions<
  Awaited<ReturnType<typeof endCaseAssignment>>,
  TError,
  EndCaseAssignmentMutationVariables,
  TContext
> => {
  const mutationKey = getEndCaseAssignmentMutationKey();
  const { mutation: mutationOptions } = options
    ? options.mutation &&
      "mutationKey" in options.mutation &&
      options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey } };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof endCaseAssignment>>,
    EndCaseAssignmentMutationVariables
  > = (props) => {
    const { caseId, assignmentId } = props ?? {};

    return endCaseAssignment(caseId, assignmentId);
  };

  return { mutationFn, ...mutationOptions };
};

