export const getListCaseActivitiesUrl = (
  caseId: string,
  params?: ListCaseActivitiesParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : String(value));
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/cases/${caseId}/activity?${stringifiedParams}`
    : `/api/cases/${caseId}/activity`;
};

export const listCaseActivities = async (
  caseId: string,
  params?: ListCaseActivitiesParams,
  options?: RequestInit,
): Promise<ListCaseActivities200> => {
  return orbitApiFetch<ListCaseActivities200>(
    getListCaseActivitiesUrl(caseId, params),
    {
      ...options,
      method: "GET",
    },
  );
};

export const getListCaseActivitiesQueryKey = (
  caseId: string,
  params?: ListCaseActivitiesParams,
) => {
  return [
    `/api/cases/${caseId}/activity`,
    ...(params ? [params] : []),
  ] as const;
};

